import * as Three from 'three';
import React from 'react';

// Shower materials
const glassMaterial = new Three.MeshPhongMaterial({
  color: 0xADD8E6,
  transparent: true,
  opacity: 0.3,
  side: Three.DoubleSide
});
const tileMaterial = new Three.MeshLambertMaterial({ color: 0xEEEEEE });
const metalMaterial = new Three.MeshLambertMaterial({ color: 0xC0C0C0 });

function makeObjectMaxLOD(newWidth, newHeight, newDepth) {
  let shower = new Three.Mesh();

  // Shower base (tile)
  let base = new Three.Mesh(
    new Three.BoxGeometry(newWidth, 5, newDepth),
    tileMaterial
  );
  base.position.y = 2.5;
  shower.add(base);

  // Glass walls (3 sides)
  // Front left wall
  let wallFront1 = new Three.Mesh(
    new Three.BoxGeometry(2, newHeight, newDepth),
    glassMaterial
  );
  wallFront1.position.x = -newWidth / 2 + 15;
  wallFront1.position.y = newHeight / 2;
  shower.add(wallFront1);

  // Front right wall
  let wallFront2 = new Three.Mesh(
    new Three.BoxGeometry(2, newHeight, newDepth),
    glassMaterial
  );
  wallFront2.position.x = newWidth / 2 - 15;
  wallFront2.position.y = newHeight / 2;
  shower.add(wallFront2);

  // Side wall (left)
  let wallLeft = new Three.Mesh(
    new Three.BoxGeometry(newWidth, newHeight, 2),
    glassMaterial
  );
  wallLeft.position.z = -newDepth / 2;
  wallLeft.position.y = newHeight / 2;
  shower.add(wallLeft);

  // Side wall (right)
  let wallRight = new Three.Mesh(
    new Three.BoxGeometry(newWidth, newHeight, 2),
    glassMaterial
  );
  wallRight.position.z = newDepth / 2;
  wallRight.position.y = newHeight / 2;
  shower.add(wallRight);

  // Shower head (simple cylinder)
  let showerHead = new Three.Mesh(
    new Three.CylinderGeometry(8, 8, 5, 16),
    metalMaterial
  );
  showerHead.position.y = newHeight - 10;
  showerHead.position.x = -newWidth / 3;
  showerHead.position.z = -newDepth / 3;
  shower.add(showerHead);

  // Shower pipe
  let pipe = new Three.Mesh(
    new Three.CylinderGeometry(1.5, 1.5, newHeight - 20, 8),
    metalMaterial
  );
  pipe.position.y = (newHeight - 20) / 2 + 5;
  pipe.position.x = -newWidth / 3;
  pipe.position.z = -newDepth / 3;
  shower.add(pipe);

  return shower;
}

function makeObjectMinLOD(newWidth, newHeight, newDepth) {
  let shower = new Three.Mesh();

  // Simplified shower - just base and glass box
  let base = new Three.Mesh(
    new Three.BoxGeometry(newWidth, 5, newDepth),
    tileMaterial
  );
  base.position.y = 2.5;
  shower.add(base);

  // Glass box
  let glass = new Three.Mesh(
    new Three.BoxGeometry(newWidth, newHeight, newDepth),
    glassMaterial
  );
  glass.position.y = newHeight / 2;
  shower.add(glass);

  return shower;
}

export default {
  name: 'douche',
  prototype: 'items',

  info: {
    tag: ['salle de bain', 'sanitaire'],
    title: 'Douche',
    description: 'Cabine de douche avec paroi vitrée',
    image: require('./shower.png')
  },

  properties: {
    width: {
      label: 'width',
      type: 'length-measure',
      defaultValue: {
        length: 80,
        unit: 'cm'
      }
    },
    depth: {
      label: 'depth',
      type: 'length-measure',
      defaultValue: {
        length: 80,
        unit: 'cm'
      }
    },
    altitude: {
      label: 'altitude',
      type: 'length-measure',
      defaultValue: {
        length: 0,
        unit: 'cm'
      }
    }
  },

  render2D: function (element, layer, scene) {
    let newWidth = element.properties.get('width').get('length');
    let newDepth = element.properties.get('depth').get('length');
    let angle = element.rotation + 90;

    let textRotation = 0;
    if (Math.sin(angle * Math.PI / 180) < 0) {
      textRotation = 180;
    }

    return (
      <g transform={`translate(${-newWidth / 2},${-newDepth / 2})`}>
        {/* Base */}
        <rect key="1" x="0" y="0" width={newWidth} height={newDepth}
          style={{stroke: element.selected ? '#0096fd' : 'none', strokeWidth: element.selected ? "2px" : "0", fill: "#E0F0FF"}}/>
        {/* Glass door opening indicator */}
        <line key="2" x1={newWidth * 0.2} y1="0" x2={newWidth * 0.8} y2="0"
          style={{stroke: element.selected ? "#999" : "#DDD", strokeWidth: "2px", strokeDasharray: "5,5"}}/>
        {/* Shower head indicator */}
        <circle key="3" cx={newWidth * 0.3} cy={newDepth * 0.3} r="5"
          style={{stroke: element.selected ? "#666" : 'none', strokeWidth: element.selected ? "1px" : "0", fill: "#CCC"}}/>
        <text key="4" x="0" y="0"
          transform={`translate(${newWidth / 2}, ${newDepth / 2}) scale(1,-1) rotate(${textRotation})`}
          style={{textAnchor: "middle", fontSize: "11px"}}>
          Douche
        </text>
      </g>
    )
  },

  render3D: function (element, layer, scene) {
    let newWidth = element.properties.get('width').get('length');
    let newDepth = element.properties.get('depth').get('length');
    let newHeight = 200; // Fixed height for showers
    let newAltitude = element.properties.get('altitude').get('length');

    /********** lod max ************/
    let showerMaxLOD = new Three.Object3D();
    let objectMaxLod = makeObjectMaxLOD(newWidth, newHeight, newDepth);
    showerMaxLOD.add(objectMaxLod.clone());
    showerMaxLOD.position.y += newAltitude;

    /********** lod min ************/
    let showerMinLOD = new Three.Object3D();
    let objectMinLod = makeObjectMinLOD(newWidth, newHeight, newDepth);
    showerMinLOD.add(objectMinLod.clone());
    showerMinLOD.position.y += newAltitude;

    /**** all level of detail ***/
    let lod = new Three.LOD();
    lod.addLevel(showerMaxLOD, 200);
    lod.addLevel(showerMinLOD, 900);
    lod.updateMatrix();
    lod.matrixAutoUpdate = false;

    if (element.selected) {
      let bbox = new Three.BoxHelper(lod, 0x99c3fb);
      bbox.material.linewidth = 5;
      bbox.renderOrder = 1000;
      bbox.material.depthTest = false;
      lod.add(bbox);
    }

    return Promise.resolve(lod);
  }
};
