import * as Three from 'three';
import React from 'react';

const textureLoader = new Three.TextureLoader();

// Bed materials
const mattressMaterial = new Three.MeshLambertMaterial({ color: 0xE8E8E8 });
const frameMaterial = new Three.MeshLambertMaterial({ color: 0x8B7355 });
const pillowMaterial = new Three.MeshLambertMaterial({ color: 0xFFFFFF });

function makeObjectMaxLOD(newWidth, newHeight, newDepth) {
  let bed = new Three.Mesh();

  // Bed frame (slightly larger than mattress)
  let frame = new Three.Mesh(
    new Three.BoxGeometry(newWidth + 5, newHeight * 0.2, newDepth + 5),
    frameMaterial
  );
  frame.position.y = newHeight * 0.1;
  bed.add(frame);

  // Mattress
  let mattress = new Three.Mesh(
    new Three.BoxGeometry(newWidth, newHeight * 0.6, newDepth),
    mattressMaterial
  );
  mattress.position.y = newHeight * 0.5;
  bed.add(mattress);

  // Pillow
  let pillow = new Three.Mesh(
    new Three.BoxGeometry(newWidth * 0.6, newHeight * 0.3, newDepth * 0.2),
    pillowMaterial
  );
  pillow.position.y = newHeight * 0.75;
  pillow.position.z = newDepth * 0.35;
  bed.add(pillow);

  return bed;
}

function makeObjectMinLOD(newWidth, newHeight, newDepth) {
  let bed = new Three.Mesh();

  // Simplified bed - just mattress
  let mattress = new Three.Mesh(
    new Three.BoxGeometry(newWidth, newHeight * 0.6, newDepth),
    mattressMaterial
  );
  mattress.position.y = newHeight * 0.3;
  bed.add(mattress);

  return bed;
}

export default {
  name: 'lit-simple',
  prototype: 'items',

  info: {
    tag: ['mobilier', 'chambre'],
    title: 'Lit 1 place',
    description: 'Lit simple une place pour chambre',
    image: require('./bed-single.png')
  },

  properties: {
    width: {
      label: 'width',
      type: 'length-measure',
      defaultValue: {
        length: 90,
        unit: 'cm'
      }
    },
    depth: {
      label: 'depth',
      type: 'length-measure',
      defaultValue: {
        length: 190,
        unit: 'cm'
      }
    },
    height: {
      label: 'height',
      type: 'length-measure',
      defaultValue: {
        length: 50,
        unit: 'cm'
      }
    },
    altitude: {
      label: 'altitude',
      type: 'length-measure',
      defaultValue: {
        length: 0,
        unit: 'cm'
      }
    }
  },

  render2D: function (element, layer, scene) {
    let newWidth = element.properties.get('width').get('length');
    let newDepth = element.properties.get('depth').get('length');
    let angle = element.rotation + 90;

    let textRotation = 0;
    if (Math.sin(angle * Math.PI / 180) < 0) {
      textRotation = 180;
    }

    return (
      <g transform={`translate(${-newWidth / 2},${-newDepth / 2})`}>
        <rect key="1" x="0" y="0" width={newWidth} height={newDepth}
          style={{stroke: element.selected ? '#0096fd' : 'none', strokeWidth: element.selected ? "2px" : "0", fill: "#E8E8E8"}}/>
        {/* Pillow indicator */}
        <rect key="2" x={newWidth * 0.2} y={newDepth * 0.75} width={newWidth * 0.6} height={newDepth * 0.2}
          style={{stroke: element.selected ? "#999" : 'none', strokeWidth: element.selected ? "1px" : "0", fill: "#FFF"}}/>
        <text key="3" x="0" y="0"
          transform={`translate(${newWidth / 2}, ${newDepth / 2}) scale(1,-1) rotate(${textRotation})`}
          style={{textAnchor: "middle", fontSize: "11px"}}>
          Lit 1P
        </text>
      </g>
    )
  },

  render3D: function (element, layer, scene) {
    let newWidth = element.properties.get('width').get('length');
    let newDepth = element.properties.get('depth').get('length');
    let newHeight = element.properties.get('height').get('length');
    let newAltitude = element.properties.get('altitude').get('length');

    /********** lod max ************/
    let bedMaxLOD = new Three.Object3D();
    let objectMaxLod = makeObjectMaxLOD(newWidth, newHeight, newDepth);
    bedMaxLOD.add(objectMaxLod.clone());
    bedMaxLOD.position.y += newAltitude;

    /********** lod min ************/
    let bedMinLOD = new Three.Object3D();
    let objectMinLod = makeObjectMinLOD(newWidth, newHeight, newDepth);
    bedMinLOD.add(objectMinLod.clone());
    bedMinLOD.position.y += newAltitude;

    /**** all level of detail ***/
    let lod = new Three.LOD();
    lod.addLevel(bedMaxLOD, 200);
    lod.addLevel(bedMinLOD, 900);
    lod.updateMatrix();
    lod.matrixAutoUpdate = false;

    if (element.selected) {
      let bbox = new Three.BoxHelper(lod, 0x99c3fb);
      bbox.material.linewidth = 5;
      bbox.renderOrder = 1000;
      bbox.material.depthTest = false;
      lod.add(bbox);
    }

    return Promise.resolve(lod);
  }
};
